export type EffectiveDeliverySelectionResourceInput = { "audience": ("merchant") & ("merchant"); "delivery_selection"?: (({ /** Delivery charge committed by this selection. */ "amount_money": MoneyValueInput; /** Buyer location snapshot used to evaluate pickup proximity. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "buyer_location"?: DeliveryBuyerLocationResourceInput; /** Deadline after which calculated pricing evidence is no longer valid. Format: date-time. */ "calculation_expires_at": string | globalThis.Date; /** Checkout session that owns the selection. */ "checkout_session_id": string; /** One chosen option for each required choice group. */ "choices": Array<DeliverySelectionChoiceResourceInput>; /** Time the selection was created. Format: date-time. */ "created_at": string | globalThis.Date; /** Quote from which this selection was made. */ "delivery_quote_id": string; /** Quote revision from which this selection was created. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "delivery_quote_revision": string; /** Stable delivery selection ID. */ "delivery_selection_id": string; /** Destination address snapshot used for delivery evaluation. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "destination_address"?: DeliveryAddressResourceInput; /** Checkout eligibility-context revision evaluated by this selection. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 0. */ "eligibility_context_revision": string; /** Deadline after which this provisional selection can no longer be committed. Format: date-time. */ "expires_at": string | globalThis.Date; /** Inputs this selection still needs before payment: each recipient field a chosen option requires that the selection does not include. Each entry repeats the quote's requirement for that option, with the same delivery_input_requirement_id. Payment fails with DELIVERY_RECIPIENT_REQUIRED until a new delivery selection includes them. Empty when nothing is missing, and always empty unless status is selected. */ "input_requirements": Array<DeliveryInputRequirementInput>; /** Buyer-provided delivery instructions. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "instructions"?: string; /** Ordered lifecycle events recorded for this selection. */ "lifecycle_events"?: Array<DeliverySelectionLifecycleEventResourceInput>; /** Time the selection lifecycle last changed. Format: date-time. */ "lifecycle_updated_at": string | globalThis.Date; /** Constraint that determined the selection expiry. */ "limiting_deadline_reason": "selection_guarantee_expiry" | "calculation_expiry" | "selection_maximum_lifetime" | "inventory_reservation_expiry" | "tax_validity_expiry" | "checkout_session_expiry"; /** Order affected by the selection. */ "order_id": string; /** Availability state of merchant-private selection evidence. */ "private_data_status"?: "available" | "redacted"; /** Recipient details captured with the selection. Omitted for a checkout session credential that doesn't act for the customer the buyer verified. */ "recipient"?: DeliveryRecipientResourceInput; /** Time merchant-private selection evidence was redacted. Format: date-time. */ "redacted_at"?: string | globalThis.Date; /** Current selection lifecycle status. */ "status": "selected" | "locked_for_payment" | "committed" | "superseded" | "expired" | "released"; }) | (null)); "mutable": boolean; "originating_checkout_session_id"?: string; "source": "none" | "provisional" | "committed"; };
